using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "WealthBoxOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/WealthBoxOmenData")]
public class WealthBoxOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.WealthBoxOmenAction = delegate
		{
			if (ReferenceSingleton<AssetsReference>.Instance.DicePool.GetDicesAmount() > TriggerAmount)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(ActionValue);
				ReferenceSingleton<AssetsReference>.Instance.SaveSystem.SaveGold(saveAndStoreCache: true);
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.WealthBoxOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), TriggerAmount, ActionValue);
	}
}
